const {
    onewr,
    newchat,
    wr,
    imgcreator,
    loginOuter,
    loginer
} = require("./functions");

const path = require("path");
const fs = require("fs");

const chatbotsPath = path.join(
    __dirname,
    "chatbots.json"
);

const chatbots = JSON.parse(
    fs.readFileSync(chatbotsPath, "utf8")
);


class AI {
    constructor(chatbot) {
        if (!chatbots[chatbot]) {
            throw new Error(`Unknown chatbot: "${chatbot}". Valid options: ${Object.keys(BOT_URLS).join(", ")}`);
        }
        
        this.chatbot = chatbot;
        this.version = "1.0";
        this.tabid = null;
        this.url = chatbots.chatbot.url;
        this._initialized = false;
    }

    /**
     * باز کردن تب جدید و تست اولیه سلامت بات
     */
    async init() {
        const tab = await newchat(this.chatbot);
        
        if (!tab || !tab.tabId) {
            throw new Error("Failed to open new chat tab");
        }

        this.tabid = tab.tabId;
        this.url = tab.url;

        // تست سلامت با یک درخواست ساده
        const req = await onewr(this.chatbot, "Hello", this.tabid);
        
        if (req && req.url) {
            this.url = req.url;
        }
        
        if (!req || !req.ok) {
            throw new Error(`Init failed: ${req?.error || "Unknown error"}`);
        }

        this._initialized = true;
        return this;
    }

    /**
     * ارسال پیام و دریافت پاسخ
     * @param {string} prompt - متن سؤال
     * @param {object} [options] - گزینه‌های اضافی (مثل timeout)
     */
    async ask(prompt, options = {}) {
        this.#checkInit();

        if (!prompt || typeof prompt !== "string") {
            throw new Error("Prompt must be a non-empty string");
        }

        const res = await wr(this.chatbot, prompt, this.tabid, this.url, options);

        if (!res || !res.ok) {
            throw new Error(`Ask failed: ${res?.error || "Unknown error"}`);
        }

        return res.text;
    }

    /**
     * تولید تصویر
     * @param {string} prompt - متن توصیف تصویر
     * @param {object} [options] - گزینه‌هایی مثل returnAll (برای برگرداندن همه عکس‌ها)
     * @returns {string|string[]} URL آخرین عکس یا آرایه‌ای از همه عکس‌ها
     */
    async createimg(prompt, options = {}) {
        this.#checkInit();
        
        console.log(`[${this.chatbot}] Creating image:`, prompt);

        const res = await imgcreator(this.chatbot, prompt, this.tabid, this.url);

        if (!res || !res.ok || !Array.isArray(res.imgurl) || res.imgurl.length === 0) {
            throw new Error(`Image creation failed: ${res?.error || "No images returned"}`);
        }

        // اگر کاربر بخواهد همه عکس‌ها را داشته باشد
        if (options.returnAll) {
            return res.imgurl;
        }

        return res.imgurl.at(-1);
    }

    /**
     * خروج از حساب کاربری (لاگ‌اوت)
     * ⚠️ بعد از اجرا، تب و URL بازنشانی می‌شوند
     */
    async login_out() {
        this.#checkInit();
        
        const res = await loginOuter(this.chatbot, this.tabid, this.url);
        console.log(`[${this.chatbot}] Logout result:`, res);
        
        if (res && res.ok) {
            // بعد از لاگ‌اوت، وضعیت تب نامشخص است
            this._initialized = false;
        }
        
        return res;
    }

    /**
     * ورود به حساب کاربری
     * @param {string} email 
     * @param {string} password 
     * @param {object} [options] - گزینه‌هایی مثل tabid, url
     */
    async login(email, password, options = {}) {
        // اگر تبی باز نشده، یک تب جدید باز می‌کنیم
        if (!this.tabid) {
            const tab = await newchat(this.chatbot);
            if (!tab || !tab.tabId) {
                throw new Error("Failed to open tab for login");
            }
            this.tabid = tab.tabId;
            this.url = tab.url;
        }

        const targetTabId = options.tabid || this.tabid;
        const targetUrl = options.url || this.url;

        if (!email || !password) {
            throw new Error("Email and password are required");
        }

        const res = await loginer(
            this.chatbot,
            email,
            password,
            targetTabId,
            targetUrl
        );
        
        console.log(`[${this.chatbot}] Login result:`, res);
        return res;
    }

    /**
     * بررسی وضعیت سلامت بات
     * @returns {boolean} آیا بات آماده کار است؟
     */
    isReady() {
        return this._initialized && this.tabid !== null;
    }

    /**
     * بستن تب و آزادسازی منابع
     */
    async close() {
        if (this.tabid && chrome?.tabs?.remove) {
            try {
                await chrome.tabs.remove(this.tabid);
            } catch (e) {
                console.warn("Could not close tab:", e);
            }
        }
        this.tabid = null;
        this.url = BOT_URLS[this.chatbot];
        this._initialized = false;
    }

    // متد خصوصی
    #checkInit() {
        if (!this._initialized || !this.tabid) {
            throw new Error("AI not initialized. Call init() first.");
        }
    }
}

module.exports = AI;